<script>
import Layout from "../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
  },
  data() {
    return {
      accounts: [],
      basic_Salary_title: "العلاوة",
      basic_Salary_title_en: "Allawance",
      salary_items: [],
      kassalaItems: [],
      kassalaItem: {
        isNewInKassala: 0,
      },
      // search
      selectedAccounts: null,
      levelThreeAccountId: null,
      levelThreeAdAccountId: null,
      // levelThreeAccounts: [],
      levelThreeAdAccounts: [],
      girbaItems: [],
      halfaItems: [],
      branchItems: [],
      levelThreeAccounts: [],
      salaryItemsData: [],
      SalaryItems: {},
      total_degrees: 17,
      salaryItemsDegrees: [],
      salaryItemDegreesHead: [],
      page: 1,
      limit: 20,
      isNewInGirba: 0,
      isNewInHalfa: 0,
      tot_pages: 0,
      searchSalaryItems: null,
      SearchMode: false,
      selectedInput: null,
      isClicked: false,
      itemId: null,
      selectedItem: null,
      salaryItemDegreeId: null,
      salaryItemsTypes: [],
      branch_id: null,
      // appprices:[]
    };
  },
  methods: {

    searchAccounts(account) {
      console.log(account);
      this.levelThreeAccountId = account?.search?.split("-")[0];
      console.log(this.levelThreeAccountId);
      this.levelTwoAccounts = [];
      this.http
        .post("level-three-chart-of-accounts-copy-1/accounts-setup/salary-item-branches", {
          leveThreeId: this.levelThreeAccountId,
          id: account.id,
        })
        .then((res) => {
          if (res.status) {
            console.log("done");
            account.search = "";
            this.getBranchesItems();
          }
        });
    },
    selectedAccount(account) {
      this.http
        .post("salary-items/types/setup/accounts/search", {
          search: account.search,
          type: "account",
        })
        .then((res) => {
          if (res.status) {
            this.levelThreeAccounts = res.data.map((a) => {
              return this.$i18n.locale == "ar"
                ? a.code + "-" + a.name
                : a.code + "-" + a.name_en;
            });
          }
        });
    },
    preEditSalaryItem(salary) {
      var data = {
        title: "popups.editsalaryItem",
        inputs: [
          {
            model: "popups.name_ar",
            type: "text",
            label: "popups.name",
            value: salary.name,
          },
          {
            model: "name_en",
            type: "text",
            label: "popups.name_en",
            value: salary.name_en,
          },

          {
            model: "start_degree",
            type: "select",
            label: "salaryItems.start_degree",
            value:salary.start_degree,
            options: [
              { value: 1, label: 1, checked: true },
              { value: 2, label: 2 },
              { value: 3, label: 3 },
              { value: 4, label: 4 },
              { value: 5, label: 5 },
              { value: 6, label: 6 },
              { value: 7, label: 7 },
              { value: 8, label: 8 },
              { value: 9, label: 9 },
              { value: 10, label: 10 },
              { value: 11, label: 11 },
              { value: 12, label: 12 },
              { value: 13, label: 13 },
              { value: 14, label: 14 },
              { value: 15, label: 15 },
              { value: 16, label: 16 },
              { value: 17, label: 17 },
            ],
          },
        ],
        buttons: [
          {
            text: "popups.edit",
            closer: true,
            color: "primary",
            handler: (obj) => {
              this.http.put("salary-items", salary.id, obj).then(() => {
                this.get(this.page);
                this.getSalaryItems()
              });
            },
          },
          {
            text: "popups.cancel",
            closer: true,
            color: "danger",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },
    addSalaryItems() {
      var data = {
        title: "popups.addsalaryitem",
        inputs: [
          { model: "name", type: "text", label: "popups.name_ar" },
          { model: "name_en", type: "text", label: "popups.name_en" },
          {
            model: "start_degree",
            type: "select",
            label: "salaryItems.start_degree",
            options: [
              { value: 1, label: 1, checked: true },
              { value: 2, label: 2 },
              { value: 3, label: 3 },
              { value: 4, label: 4 },
              { value: 5, label: 5 },
              { value: 6, label: 6 },
              { value: 7, label: 7 },
              { value: 8, label: 8 },
              { value: 9, label: 9 },
              { value: 10, label: 10 },
              { value: 11, label: 11 },
              { value: 12, label: 12 },
              { value: 13, label: 13 },
              { value: 14, label: 14 },
              { value: 15, label: 15 },
              { value: 16, label: 16 },
              { value: 17, label: 17 },
            ],
          },
        ],
        buttons: [
          {
            text: "popups.add",
            closer: true,
            color: "primary",
            handler: (obj) => {
              console.log(obj);
              
              this.http.post("salary-items", obj).then(() => {
                this.get(this.page);
                this.getSalaryItems()
              });
            },
          },
          {
            text: "popups.cancel",
            closer: true,
            color: "danger",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },
    search() {
      this.SearchMode = true;
      this.tot_pages = 0;
      this.http
        .post("salary-items/search", {
          search: this.searchSalaryItems,
          limit: this.limit,
          page: this.page,
          col: "name",
        })
        .then((res) => {
          this.salary_items = res.data;
        });
    },
    addSalaryItemBranch(branch_id) {
      console.log(branch_id);
      let locale = this.$i18n.locale;
      this.http
        .post("salary-items-branches/get-all-items-except", { branch_id })
        .then((resp) => {
          this.salaryItemsData = resp.data;
          var data = {
            title: "popups.addsalaryitem",
            inputs: [
              {
                model: "salary_item_id",
                type: "select",
                options: (() => {
                  return this.salaryItemsData.map((data) => {
                    return {
                      value: data.id,
                      label: locale == "ar" ? data.name : data.name_en,
                    };
                  });
                })(),
                label: "salaryItems.chose_salary_item",
              },
            ],
            buttons: [
              {
                text: "popups.add",
                closer: true,
                color: "primary",
                handler: (obj) => {
                  obj.branch_id = branch_id;
                  this.http.post("salary-items-branches", obj).then(() => {
                    this.getBranchItems(branch_id);
                  });
                },
              },
              {
                text: "popups.cancel",
                closer: true,
                color: "danger",
                handler: () => {
                  console.log("Like Clicked");
                },
              },
            ],
          };
          this.popup.modal(data);
        });
    },
    getBranchItems(branch_id) {
      this.http
        .post("salary-items-branches/branch-items", { branch_id })
        .then((resp) => {
          if (branch_id == 1) {
            this.kassalaItems = resp.data;
          }
          if (branch_id == 2) {
            this.girbaItems = resp.data;
          }
          if (branch_id == 3) {
            this.halfaItems = resp.data;
          }
        });
    },
    deleteSalaryBranchItem(id, branch_id) {
      var data = {
        title: "popups.delete",
        msg: "popups.deletemsg",
      };
      this.popup.confirm(data).then((res) => {
        if (res) {
          this.http
            .post("salary-items-branches/delete", {
              salary_item_id: id,
              branch_id: branch_id,
            })
            .then(() => {
              this.getBranchItems(branch_id);
            });
        }
      });
    },
    getBranchesItems() {
      this.http
        .post("salary-items-branches/all-items", { branch_id: this.branch_id })
        .then((resp) => {
          this.kassalaItems = resp.kassalaItems;
          this.girbaItems = resp.girbaItems;
          this.halfaItems = resp.halfaItems;
        });
    },
    cancelappsearchMode() {
      this.searchSalaryItems = "";
      this.SalaryItemsSearchMode = false;
      this.get(this.page);
    },
    getSalaryItems() {
      this.http.get("salary-item-degrees/degrees").then((res) => {
        this.salaryItemsDegrees = res.data;
        this.salaryItemDegreesHead = res.salaryItemDegreesHeader;
        console.log("salaryItemsDegrees", this.salaryItemsDegrees);
        console.log("salaryItemDegreesHead", this.salaryItemDegreesHead);
      });
    },
    deleteSalaryItems(app) {
      var data = {
        title: "popups.deletesalaryItem",
        msg: "popups.deletemsg",
      };
      this.popup.confirm(data).then((res) => {
        if (res) {
          this.http.delete("salary-items", app.id).then(() => {
            this.get(this.page);
          });
        }
      });
    },
    cancelSearchMode() {
      this.searchSalaryItems = "";
      this.SearchMode = false;
      this.get(this.page);
    },
    updatedSalaryItemBasicValue(event, item, value,degree) {
     let data = {
       ["value"+value]: parseFloat(event.target.value),
       salary_item_id:item.salary_item.id,
       degree
     }
     if(item.id)
      this.http.put("salary-item-degrees", item.id, data).then((resp) => {
        if (resp.status) {
          this.getSalaryItems()
        }
      });
     else
       this.http.post("salary-item-degrees", data).then((resp) => {
         if (resp.status) {
           this.getSalaryItems()
         }
       });
    },
    updatedSalaryItemValue(event, item,degree) {
      if(item.id)
      this.http
        .put("salary-item-degrees", item.id, {
          value: parseFloat(event.target.value),
        })
        .then((resp) => {
          if (resp.status) {
            this.getSalaryItems()
          }
        });
      else{
        this.http
            .post("salary-item-degrees", {
              value: parseFloat(event.target.value),
              salary_item_id:item.salary_item.id,
              degree
            })
            .then((resp) => {
              if (resp.status) {
                this.getSalaryItems()
              }
            });
      }
    },

    get(page) {
      console.log(page);
      this.http
        .post("salary-items/pagination", {
          limit: this.limit,
          page: page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.salary_items = res.data;
        });
    },
  },
  computed: {
    filteredKassalaAccounts() {
      return this.levelThreeAccounts.filter((account) => {
        return account;
      });
    },
    // filteredGirbaAccounts() {
    //   return this.levelThreeAccounts.filter((account) => {
    //     return account;
    //   });
    // },
    filteredAccounts() {
      return this.levelThreeAccounts.filter((account) => {
        return account;
      });
    },
    filteredHalfaAccounts() {
      return this.levelThreeAccounts.filter((account) => {
        return account;
      });
    },
  },
  created() {
    this.get(1);
    this.getSalaryItems();
    this.getBranchesItems();
  },
};
</script>

